// AUTOGENERATED. DO NOT MODIFY.
// To modify this file, run: node scripts/m3/gen-keyboard-tests.mjs radio
// Spec: m3.material.io 2026-10-13_06-10-19, radio-button "Keyboard navigation"
//
// Each case presses real keys and checks the behavior the spec's keyboard
// table lists for that key. `xit` cases are known differences from the spec.

// import 'jasmine'; (google3-only)
import {sendKeys} from '@web/test-runner-commands';
import {html, render, type ReactiveElement, type TemplateResult} from 'lit';
import './md-gb-radio.js';
import {type RadioElement} from './radio-element.js';

interface SetupOptions {
  /** Index of the item to render selected. */
  selected?: number;
  /** Value step (sliders). */
  step?: number;
}

interface Fixture {
  root: HTMLElement;
  items: HTMLElement[];
  before: HTMLElement;
  after: HTMLElement;
  /** Indices of the items that received a click (activation). */
  activated: number[];
  // Menus.
  invoker?: HTMLElement;
  menu?: HTMLElement;
  submenu?: HTMLElement;
  submenuItems?: HTMLElement[];
}

let container: HTMLElement | undefined;

async function mount(template: TemplateResult) {
  container?.remove();
  container = document.createElement('div');
  document.body.appendChild(container);
  render(template, container);
  await settle();
  return container;
}

function fixture(root: HTMLElement, items: HTMLElement[]): Fixture {
  const activated: number[] = [];
  items.forEach((item, i) => {
    item.addEventListener('click', (event) => {
      // Clicks bubbling from nested items (submenus) are not this item's.
      const path = event.composedPath();
      if (path.find((el) => items.includes(el as HTMLElement)) === item) {
        activated.push(i);
      }
    });
  });
  return {
    root,
    items,
    activated,
    before: root.querySelector<HTMLElement>('#before')!,
    after: root.querySelector<HTMLElement>('#after')!,
  };
}

/** Waits for Lit updates, a frame and pending timeouts. */
async function settle(root: ParentNode = document.body) {
  for (const el of root.querySelectorAll('*')) {
    const update = (el as Partial<ReactiveElement>).updateComplete;
    if (update) await update;
    if (el.shadowRoot) await settle(el.shadowRoot);
  }
  if (root !== document.body) return;
  // Twice: popover toggle events, and the timeouts they start, can land
  // after the next frame.
  for (let i = 0; i < 2; i++) {
    await new Promise((resolve) => requestAnimationFrame(resolve));
    await new Promise((resolve) => setTimeout(resolve));
  }
}

/** Presses a key (or a chord such as `Shift+Tab`) on a real keyboard. */
async function press(key: string) {
  await sendKeys({press: key});
  await settle();
}

/** The focused element and the focused elements of its shadow roots. */
function focusPath() {
  const path: Element[] = [];
  let el = document.activeElement;
  while (el) {
    path.push(el);
    el = el.shadowRoot?.activeElement ?? null;
  }
  return path;
}

/** The index of the item that holds focus, or -1. */
function focusedIndex(items: Element[]) {
  const path = focusPath();
  return items.findIndex((item) =>
    path.some((el) => el === item || item.contains(el)),
  );
}

/** Focuses item `index` (negative counts from the end). */
async function focusItem(f: Fixture, index: number) {
  f.items[(index + f.items.length) % f.items.length].focus();
  await settle();
}

async function setup(opts: SetupOptions = {}): Promise<Fixture> {
  const root = await mount(html`
    <button id="before">Before</button>
    <div role="radiogroup" aria-label="Size">
      ${[0, 1, 2].map(
        (i) =>
          html`<md-gb-radio
            name="size"
            value=${i}
            aria-label="Option ${i}"
            ?checked=${opts.selected === i}></md-gb-radio>`,
      )}
    </div>
    <button id="after">After</button>
  `);
  return fixture(root, [...root.querySelectorAll<HTMLElement>('md-gb-radio')]);
}

function selectedIndices(f: Fixture) {
  return f.items.flatMap((item, i) =>
    (item as RadioElement).checked ? [i] : [],
  );
}

describe('<md-gb-radio> keyboard (spec)', () => {
  afterEach(() => {
    container?.remove();
    container = undefined;
  });

  // Spec: "Tab" | "Moves focus into the group to the selected radio button, or the first if none are selected"
  // spec: radio-button-02eb5d, radio-button-342ba1, radio-button-c144f6
  describe("Tab: Moves focus into the group to the selected radio button, or the first if none are selected", () => {
    it("Tab moves focus to the first item when none is selected", async () => {
      const f = await setup();
      f.before.focus();
      await press('Tab');
      expect(focusedIndex(f.items)).toBe(0);
    });

    it("Tab moves focus to the selected item", async () => {
      const f = await setup({selected: 1});
      f.before.focus();
      await press('Tab');
      expect(focusedIndex(f.items)).toBe(1);
    });
  });

  // Spec: "Shift + Tab" | "Moves focus into the group to the selected radio button, or the last if none are selected"
  // spec: radio-button-0f62bd, radio-button-342ba1
  describe("Shift + Tab: Moves focus into the group to the selected radio button, or the last if none are selected", () => {
    it("Shift+Tab moves focus to the last item when none is selected", async () => {
      const f = await setup();
      f.after.focus();
      await press('Shift+Tab');
      expect(focusedIndex(f.items)).toBe(f.items.length - 1);
    });

    it("Shift+Tab moves focus to the selected item", async () => {
      const f = await setup({selected: 1});
      f.after.focus();
      await press('Shift+Tab');
      expect(focusedIndex(f.items)).toBe(1);
    });
  });

  // Spec: "Arrows" | "Moves focus and selects the previous or next radio button. Wraps focus and selection between the first and last radio buttons."
  // spec: radio-button-4a92aa, radio-button-fa995d, radio-button-5154cb
  describe("Arrows: Moves focus and selects the previous or next radio button. Wraps focus and selection between the first and last radio buttons.", () => {
    it("ArrowRight moves focus to the next item and selects it", async () => {
      const f = await setup();
      await focusItem(f, 0);
      await press('ArrowRight');
      expect(focusedIndex(f.items)).toBe(1);
      expect(selectedIndices(f)).toEqual([1]);
    });

    it("ArrowRight wraps from the last item to the first and selects it", async () => {
      const f = await setup();
      await focusItem(f, -1);
      await press('ArrowRight');
      expect(focusedIndex(f.items)).toBe(0);
      expect(selectedIndices(f)).toEqual([0]);
    });

    it("ArrowLeft moves focus to the previous item and selects it", async () => {
      const f = await setup();
      await focusItem(f, 1);
      await press('ArrowLeft');
      expect(focusedIndex(f.items)).toBe(0);
      expect(selectedIndices(f)).toEqual([0]);
    });

    it("ArrowLeft wraps from the first item to the last and selects it", async () => {
      const f = await setup();
      await focusItem(f, 0);
      await press('ArrowLeft');
      expect(focusedIndex(f.items)).toBe(f.items.length - 1);
      expect(selectedIndices(f)).toEqual([f.items.length - 1]);
    });

    it("ArrowDown moves focus to the next item and selects it", async () => {
      const f = await setup();
      await focusItem(f, 0);
      await press('ArrowDown');
      expect(focusedIndex(f.items)).toBe(1);
      expect(selectedIndices(f)).toEqual([1]);
    });

    it("ArrowDown wraps from the last item to the first and selects it", async () => {
      const f = await setup();
      await focusItem(f, -1);
      await press('ArrowDown');
      expect(focusedIndex(f.items)).toBe(0);
      expect(selectedIndices(f)).toEqual([0]);
    });

    it("ArrowUp moves focus to the previous item and selects it", async () => {
      const f = await setup();
      await focusItem(f, 1);
      await press('ArrowUp');
      expect(focusedIndex(f.items)).toBe(0);
      expect(selectedIndices(f)).toEqual([0]);
    });

    it("ArrowUp wraps from the first item to the last and selects it", async () => {
      const f = await setup();
      await focusItem(f, 0);
      await press('ArrowUp');
      expect(focusedIndex(f.items)).toBe(f.items.length - 1);
      expect(selectedIndices(f)).toEqual([f.items.length - 1]);
    });
  });

  // Spec: "Space" | "Selects a focused radio button. If already selected, does nothing."
  // spec: radio-button-ebfeb5
  describe("Space: Selects a focused radio button. If already selected, does nothing.", () => {
    it("Space selects the focused item", async () => {
      const f = await setup();
      await focusItem(f, 1);
      await press('Space');
      expect(selectedIndices(f)).toContain(1);
      await press('Space');
      expect(selectedIndices(f)).toEqual([1]);
    });
  });
});
